import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Every locale carries the same keys as the source","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/locale-parity.md","filePath":"reference/rules/locale-parity.md"}`),a={name:`reference/rules/locale-parity.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="every-locale-carries-the-same-keys-as-the-source" tabindex="-1">Every locale carries the same keys as the source <a class="header-anchor" href="#every-locale-carries-the-same-keys-as-the-source" aria-label="Permalink to “Every locale carries the same keys as the source”">​</a></h1><p>Every locale must define exactly the keys the source locale defines.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>Typed translation keys prove a key exists in the source locale. Nothing proves it was copied to the others, so a key added to one locale alone silently falls back at runtime for every other language. The problem is visible only to users of those languages, which is usually nobody on the team.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><p>Add the key to the source locale, then add the identical key to every other locale. Copying the source text verbatim is the convention until a translation arrives; a placeholder in the wrong language is better than a missing key.</p><h2 id="keys-the-source-does-not-have" tabindex="-1">Keys the source does not have <a class="header-anchor" href="#keys-the-source-does-not-have" aria-label="Permalink to “Keys the source does not have”">​</a></h2><p>These are reported too. They are usually a rename applied to one locale but not the rest.</p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to “Layouts”">​</a></h2><p>Two catalog layouts are supported, selected with the <code>layout</code> option:</p><ul><li><code>directory-per-locale</code> (default): <code>locales/&lt;locale&gt;/&lt;namespace&gt;.json</code>, one directory per locale, one JSON file per namespace.</li><li><code>file-per-locale</code>: <code>locales/&lt;locale&gt;.json</code>, one flat JSON file per locale. Region codes such as <code>en-US.json</code> work.</li></ul><p>Locales are discovered from the layout. Pass <code>locales</code> explicitly to pin the set, for example when the directory also holds files that are not catalogs.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};